using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The SDK instantiates this class per-request using DI, so constructor-injected
/// services (like HttpClient) are resolved from the container automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather for a city.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        [Description("Units: 'metric' or 'imperial'")] string units = "metric")
    {
        var response = await _httpClient.GetAsync(
            $"/weather?q={Uri.EscapeDataString(city)}&units={units}");

        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync();
        return json;
    }

    [McpServerTool, Description("Get a 5-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name, e.g. 'London'")] string city)
    {
        var response = await _httpClient.GetAsync(
            $"/forecast?q={Uri.EscapeDataString(city)}&units=metric");

        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync();
        return json;
    }
}

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using ModelContextProtocol.Server;

var builder = McpServerApp.CreateBuilder(args);

builder.Services.AddMcpServerTools<WeatherTools>();

// Register a named HttpClient that gets injected into WeatherTools.
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.openweathermap.org/data/2.5");
});

await builder.BuildAndRunAsync();

